import{_ as a,c as i,o as e,a8 as n}from"./chunks/framework.igqXP-xE.js";const p="/assets/YtErbab1xopHRyxO4nQcnWwanSh.DCY05i6p.png",k=JSON.parse('{"title":"网络命令","description":"","frontmatter":{"title":"网络命令","urlname":"By3Gdf4jMoYYY7xpWT6cZ3NNnNc","date":"2025-04-02 01:01:45","updated":"2025-04-02 23:32:21"},"headers":[],"relativePath":"feishu/docs/集成文档/By3Gdf4jMoYYY7xpWT6cZ3NNnNc.md","filePath":"feishu/docs/集成文档/By3Gdf4jMoYYY7xpWT6cZ3NNnNc.md","lastUpdated":1743997366000}'),l={name:"feishu/docs/集成文档/By3Gdf4jMoYYY7xpWT6cZ3NNnNc.md"};function t(r,s,h,d,c,b){return e(),i("div",null,s[0]||(s[0]=[n('<h2 id="_1-post和put" tabindex="-1">1，POST和PUT <a class="header-anchor" href="#_1-post和put" aria-label="Permalink to &quot;1，POST和PUT&quot;">​</a></h2><p>是HTTP协议中的两种请求方法：</p><p>POST（发布） ：</p><ul><li><p>用于向服务器提交数据，通常用于创建新资源</p></li><li><p>不具有幂等性（多次相同请求可能会创建多个资源）</p></li><li><p>数据通常在请求体中传输</p></li><li><p>常见用途：提交表单、上传文件、创建新记录</p></li></ul><p>PUT（放置） ：</p><ul><li><p>用于向服务器更新资源，或者在指定位置创建资源</p></li><li><p>具有幂等性（多次相同请求产生的效果相同）</p></li><li><p>完全替换目标资源</p></li><li><p>常见用途：更新已存在的资源</p></li></ul><p><img src="'+p+`" alt="image"> 从您的日志截图来看，天猫精灵平台尝试向您的服务器发送了一个POST请求到 <a href="https://gm.mmstat.com/aes.1.1" target="_blank" rel="noreferrer">https://gm.mmstat.com/aes.1.1</a> 和一个PUT请求到 <a href="https://iap.aligenie.com/api/hybird/logicConfig" target="_blank" rel="noreferrer">https://iap.aligenie.com/api/hybird/logicConfig</a> ，但两者都失败了。</p><p>您的Home Assistant服务器已经正确响应了认证文件的GET请求，但天猫精灵平台在尝试与其自己的API通信时遇到了问题。这些错误可能与天猫精灵平台内部通信有关，而不是您的Home Assistant配置问题。</p><ul><li><p>POST 请求到 <a href="https://gm.mmstat.com/aes.1.1" target="_blank" rel="noreferrer">https://gm.mmstat.com/aes.1.1</a> 失败，显示 ERR_CONNECTION_CLOSED</p></li><li><p>PUT 请求到 <a href="https://iap.aligenie.com/api/hybird/logicConfig" target="_blank" rel="noreferrer">https://iap.aligenie.com/api/hybird/logicConfig</a> 失败，显示 403 (Forbidden)</p></li><li><p>mmstat.com 是阿里巴巴的统计和分析服务域名</p></li><li><p>iap.aligenie.com 是天猫精灵平台的API域名</p></li></ul><h2 id="_2-内网穿透" tabindex="-1">2，内网穿透 <a class="header-anchor" href="#_2-内网穿透" aria-label="Permalink to &quot;2，内网穿透&quot;">​</a></h2><p>公网访问你的开发环境，如果无公网IP可以使用内网穿透的方式来进行。推荐几个内网穿透服务如下：</p><ol><li><p><a href="https://github.com/open-dingtalk/dingtalk-pierced-client?spm=a2c6h.12873639.article-detail.6.5d844decw9AZ2W" target="_blank" rel="noreferrer">https://github.com/open-dingtalk/dingtalk-pierced-client</a><strong>（推荐，本文使用）</strong></p></li><li><p><a href="https://ngrok.com/" target="_blank" rel="noreferrer">https://ngrok.com/</a></p></li><li><p><a href="https://natapp.cn/" target="_blank" rel="noreferrer">https://natapp.cn/</a></p></li><li><p><a href="https://hsk.oray.com/" target="_blank" rel="noreferrer">https://hsk.oray.com/</a></p></li><li><p><a href="https://expose.dev/" target="_blank" rel="noreferrer">https://expose.dev/</a></p></li><li><p><a href="https://github.com/fatedier/frp" target="_blank" rel="noreferrer">https://github.com/fatedier/frp</a> 自建</p></li><li><p><a href="https://github.com/ehang-io/nps" target="_blank" rel="noreferrer">https://github.com/ehang-io/nps</a> 自建</p></li></ol><h2 id="_3-iptables" tabindex="-1">3，iptables <a class="header-anchor" href="#_3-iptables" aria-label="Permalink to &quot;3，iptables&quot;">​</a></h2><p>iptables 是 Linux 系统中用于配置网络防火墙的命令行工具，它允许您设置、维护和检查 IPv4 数据包过滤规则。以下是 iptables 的基本使用方法：</p><h3 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h3><p>iptables 使用&quot;表&quot;和&quot;链&quot;的概念来组织规则：</p><ul><li><p>表(tables)：filter(默认)、nat、mangle、raw 等</p></li><li><p>链(chains)：INPUT、OUTPUT、FORWARD 等</p></li></ul><h3 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h3><ol><li>查看当前规则</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -v</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol><li>添加规则</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 允许特定端口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -A</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> INPUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> tcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --dport</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> 8123</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -j</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ACCEPT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>3. 删除规则</span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span># 删除特定规则</span></span>
<span class="line"><span>sudo iptables -D INPUT -p tcp --dport 8123 -j ACCEPT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>4. 设置默认策略</span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>sudo iptables -P INPUT ACCEPT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ol><li>保存规则</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> iptables-save</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> /etc/iptables/rules.v4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="6"><li>恢复规则</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>sudo iptables-restore &lt; /etc/iptables/rules.v4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span>### 实用示例</span></span>
<span class="line"><span>1. 允许 Home Assistant 端口</span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>sudo iptables -A INPUT -p tcp --dport 8123 -j ACCEPT</span></span>
<span class="line"><span>2. 允许已建立的连接</span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>sudo iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT</span></span>
<span class="line"><span>3. 阻止特定 IP</span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>sudo iptables -A INPUT -s 192.168.1.100 -j DROP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>如果您经常使用 iptables，可以考虑在 .bashrc 中添加一些别名来简化操作：</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0"><code><span class="line"><span># iptables 快捷命令</span></span>
<span class="line"><span>alias ipt=&#39;sudo iptables&#39;</span></span>
<span class="line"><span>alias iptlist=&#39;sudo iptables -L -v --line-numbers&#39;</span></span>
<span class="line"><span>alias iptsave=&#39;sudo iptables-save &gt; /etc/iptables/rules.v4&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ... 现有代码 ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div>`,31)]))}const u=a(l,[["render",t]]);export{k as __pageData,u as default};
